CHAT_B_ID = -1002370495864  # chat_id закрытого канала B

# Регулярное выражение для фильтрации сообщений
MESSAGE_REGEX = r"\b(репетитор|препода|педагог)\w*\b"  # Сообщения с корнями "репет", "препод", "педаг"

# Инициализация бота и диспетчера
bot = Bot(token=BOT_TOKEN)
dp = Dispatcher()


# Кастомный фильтр для проверки username группы
class ChatUsernamesFilter(BaseFilter):
    def __init__(self, chat_usernames: list[str]):
        self.chat_usernames = chat_usernames

    async def __call__(self, message: Message) -> bool:
        return message.chat.username in self.chat_usernames


# Кастомный фильтр для проверки текста сообщения по регулярному выражению
class MessageRegexFilter(BaseFilter):
    def __init__(self, pattern: str):
        self.pattern = re.compile(pattern, re.IGNORECASE)  # Игнорируем регистр

    async def __call__(self, message: Message) -> bool:
        # Проверяем, что текст есть и соответствует регулярному выражению
        return bool(message.text and self.pattern.search(message.text))


# Регистрация хендлера с несколькими фильтрами
@dp.message(ChatUsernamesFilter(CHAT_USERNAMES), MessageRegexFilter(MESSAGE_REGEX))
async def forward_message_to_channel(message: Message):
    """
    Пересылка сообщений из указанных публичных групп в закрытый канал B с добавлением ссылки на оригинальное сообщение.
    """
    try:
        # Формируем ссылку на оригинальное сообщение
        original_message_link = f"https://t.me/{message.chat.username}/{message.message_id}"

        # Отправляем сообщение в закрытый канал B
        await bot.send_message(
            CHAT_B_ID,
            f"{message.text}\n\nПерейдите по ссылке, чтобы увидеть это сообщение в группе {message.chat.title}: {original_message_link}"
        )
    except Exception as e:
        print(f"Ошибка при пересылке сообщения: {e}")


async def main():
    try:
        print("Удаление активного вебхука...")
        await bot.delete_webhook(drop_pending_updates=True)  # Удаляем вебхук и очищаем неподтвержденные обновления
        print("Бот запущен...")
        await dp.start_polling(bot)  # Запуск long-polling
    except Exception as e:
        print(f"Ошибка запуска бота: {e}")


if __name__ == "__main__":
    asyncio.run(main())


